WITH kept_keys AS (SELECT merchant, account_id FROM transactions EXCEPT DISTINCT SELECT merchant, account_id FROM transactions WHERE account_id = 32), verified AS (SELECT s.* FROM transactions s INNER JOIN kept_keys k ON s.merchant = k.merchant AND s.account_id = k.account_id) SELECT merchant, CASE WHEN amount >= 3400 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, MAX(txn_time) AS last_seen, COUNT(DISTINCT account_id) AS distinct_account_ids, MAX(txn_time) AS last_txn_time, RANK() OVER (PARTITION BY merchant ORDER BY COUNT(DISTINCT account_id) DESC) AS distinct_account_ids_rank FROM verified GROUP BY 1, 2 ORDER BY amount_tier DESC NULLS LAST;
